import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Settings — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"settings-03-advanced-and-customization.md","filePath":"settings-03-advanced-and-customization.md"}'),i={name:"settings-03-advanced-and-customization.md"};function n(s,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="settings-—-advanced-features-customization" tabindex="-1">Settings — Advanced Features &amp; Customization <a class="header-anchor" href="#settings-—-advanced-features-customization" aria-label="Permalink to &quot;Settings — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Using Settings strategically, custom evaluation frameworks, and team configuration tips</em></p><hr><h2 id="designing-your-object-type-taxonomy" tabindex="-1">Designing Your Object Type Taxonomy <a class="header-anchor" href="#designing-your-object-type-taxonomy" aria-label="Permalink to &quot;Designing Your Object Type Taxonomy&quot;">​</a></h2><p>The Taxonomy settings determine what kinds of objects exist in your workspace. Done well, a clear type taxonomy reduces ambiguity, makes the Backlog easier to filter, and enables meaningful hierarchy in Roadmaps. Done poorly, it adds friction without adding clarity.</p><h3 id="keep-the-type-list-short" tabindex="-1">Keep the type list short <a class="header-anchor" href="#keep-the-type-list-short" aria-label="Permalink to &quot;Keep the type list short&quot;">​</a></h3><p>Each additional type is a decision your team must make for every item added to the Backlog. Two to four types is a comfortable range for most teams. More than five types is usually a sign that you&#39;re trying to replicate a delivery tool like JIRA inside Lodestone — a model that doesn&#39;t fit how Lodestone works.</p><h3 id="choose-prefixes-that-are-self-evident" tabindex="-1">Choose prefixes that are self-evident <a class="header-anchor" href="#choose-prefixes-that-are-self-evident" aria-label="Permalink to &quot;Choose prefixes that are self-evident&quot;">​</a></h3><p>Prefixes appear in typed IDs and in the Type column. Choose abbreviations that are immediately recognizable to anyone on your team — FEAT for Feature, EPIC for Epic, BUG for Bug. Avoid abbreviations that overlap or could be confused.</p><h3 id="use-the-top-tier-type-to-reflect-your-actual-hierarchy" tabindex="-1">Use the top-tier type to reflect your actual hierarchy <a class="header-anchor" href="#use-the-top-tier-type-to-reflect-your-actual-hierarchy" aria-label="Permalink to &quot;Use the top-tier type to reflect your actual hierarchy&quot;">​</a></h3><p>The top-tier type should represent the highest level of planning intent in your Backlog. For most teams, this is a strategic grouping like Epic or Initiative. Items of the top-tier type can serve as parents in Roadmap hierarchies without disappearing from the Backlog.</p><h3 id="be-conservative-with-parent-child-constraints" tabindex="-1">Be conservative with parent/child constraints <a class="header-anchor" href="#be-conservative-with-parent-child-constraints" aria-label="Permalink to &quot;Be conservative with parent/child constraints&quot;">​</a></h3><p>Parent/child type constraints are a power feature — they prevent hierarchy violations — but they add complexity when items need to be retyped. Only configure constraints if your team has a stable, agreed-upon hierarchy model. If your taxonomy is still evolving, leave constraints unconfigured and revisit once patterns stabilize.</p><hr><h2 id="the-organization-description-your-most-impactful-setting" tabindex="-1">The Organization Description: Your Most Impactful Setting <a class="header-anchor" href="#the-organization-description-your-most-impactful-setting" aria-label="Permalink to &quot;The Organization Description: Your Most Impactful Setting&quot;">​</a></h2><p>Of all the Settings available, the Organization Description has the broadest impact on day-to-day usage. It feeds into every AI-generated Document across the platform — PRDs, Opportunity Canvases, User Stories, social posts, customer emails, and more.</p><p>Teams that invest time in writing a strong Organization Description consistently get better AI output. Teams that leave it blank or write something generic consistently get output that feels off-brand and irrelevant.</p><h3 id="what-to-include" tabindex="-1">What to include <a class="header-anchor" href="#what-to-include" aria-label="Permalink to &quot;What to include&quot;">​</a></h3><ul><li><strong>Industry and domain</strong> — what space you operate in</li><li><strong>Business model</strong> — SaaS, marketplace, services, hardware, etc.</li><li><strong>Customer profile</strong> — who buys from you, at what company size, in what role</li><li><strong>Product positioning</strong> — what your product does and how it&#39;s differentiated</li><li><strong>Tone and voice</strong> — if your brand has a distinct communication style, name it</li></ul><h3 id="keeping-it-current" tabindex="-1">Keeping it current <a class="header-anchor" href="#keeping-it-current" aria-label="Permalink to &quot;Keeping it current&quot;">​</a></h3><p>As your product, market, or positioning evolves, update the description. Stale context produces stale output. Treat it like a living brief — revisit it at least once per quarter.</p><hr><h2 id="designing-status-stages-for-your-team" tabindex="-1">Designing Status Stages for Your Team <a class="header-anchor" href="#designing-status-stages-for-your-team" aria-label="Permalink to &quot;Designing Status Stages for Your Team&quot;">​</a></h2><p>The default stages (Not Started, In Progress, Completed) work for many teams, but most benefit from customizing them to reflect their actual workflow. A few design principles:</p><h3 id="name-stages-from-the-feature-s-perspective-not-the-team-s" tabindex="-1">Name stages from the Feature&#39;s perspective, not the team&#39;s <a class="header-anchor" href="#name-stages-from-the-feature-s-perspective-not-the-team-s" aria-label="Permalink to &quot;Name stages from the Feature&#39;s perspective, not the team&#39;s&quot;">​</a></h3><p>&quot;In Development&quot; describes where the Feature is; &quot;Team Working&quot; describes what the team is doing. The former is clearer to stakeholders and easier to interpret on a Release board.</p><h3 id="include-stages-that-reflect-real-handoffs" tabindex="-1">Include stages that reflect real handoffs <a class="header-anchor" href="#include-stages-that-reflect-real-handoffs" aria-label="Permalink to &quot;Include stages that reflect real handoffs&quot;">​</a></h3><p>If there&#39;s a meaningful moment when a Feature moves from PM to engineering, from engineering to QA, or from QA to shipped, consider a stage for each. Stages that reflect real handoffs give stakeholders more accurate visibility.</p><h3 id="don-t-over-segment" tabindex="-1">Don&#39;t over-segment <a class="header-anchor" href="#don-t-over-segment" aria-label="Permalink to &quot;Don&#39;t over-segment&quot;">​</a></h3><p>More stages means more manual status updates. A stage is only useful if someone is responsible for moving Features into and out of it. If no one owns the transition, the stage will be stale.</p><h3 id="common-stage-sets-by-team-type" tabindex="-1">Common stage sets by team type <a class="header-anchor" href="#common-stage-sets-by-team-type" aria-label="Permalink to &quot;Common stage sets by team type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Team type</th><th>Suggested stages</th></tr></thead><tbody><tr><td>Small / agile</td><td>Not Started → In Progress → Done</td></tr><tr><td>Product + engineering</td><td>Discovery → Scoped → In Dev → In QA → Shipped</td></tr><tr><td>Enterprise / structured</td><td>Backlog → Prioritized → In Design → In Dev → In Review → Released</td></tr></tbody></table><hr><h2 id="building-a-custom-evaluation-framework" tabindex="-1">Building a Custom Evaluation Framework <a class="header-anchor" href="#building-a-custom-evaluation-framework" aria-label="Permalink to &quot;Building a Custom Evaluation Framework&quot;">​</a></h2><p>The built-in frameworks (RICE, ICE, WSJF, etc.) cover most prioritization needs, but custom frameworks let you define scoring criteria that reflect your specific business context.</p><h3 id="when-to-use-a-custom-framework" tabindex="-1">When to use a custom framework <a class="header-anchor" href="#when-to-use-a-custom-framework" aria-label="Permalink to &quot;When to use a custom framework&quot;">​</a></h3><ul><li>Your team uses internal terminology that doesn&#39;t map to standard frameworks</li><li>You need to score against factors specific to your market (e.g. regulatory compliance, partner dependency)</li><li>You want a simpler scoring model than RICE or WSJF</li></ul><h3 id="design-tips" tabindex="-1">Design tips <a class="header-anchor" href="#design-tips" aria-label="Permalink to &quot;Design tips&quot;">​</a></h3><ul><li><strong>Keep inputs to 3–5 fields</strong> — more inputs don&#39;t produce better prioritization; they produce more noise</li><li><strong>Use numeric scales, not free text</strong> — scores only aggregate if they&#39;re numeric</li><li><strong>Define the formula clearly</strong> — make sure the composite score formula reflects your actual priorities (e.g. if strategic alignment matters more than effort, weight it accordingly)</li><li><strong>Test with real Features</strong> — before rolling out a custom framework, run a sample of backlog Features through it to see if the scores feel right</li></ul><hr><h2 id="role-strategy-admins-vs-builders" tabindex="-1">Role Strategy: Admins vs Builders <a class="header-anchor" href="#role-strategy-admins-vs-builders" aria-label="Permalink to &quot;Role Strategy: Admins vs Builders&quot;">​</a></h2><p>With only two roles, role assignment is straightforward — but a few patterns are worth considering:</p><h3 id="default-to-builder" tabindex="-1">Default to Builder <a class="header-anchor" href="#default-to-builder" aria-label="Permalink to &quot;Default to Builder&quot;">​</a></h3><p>Unless someone specifically needs to change org-level settings or connect the Gong integration, Builder is the right default. It gives full access to all planning modules without the risk of accidental org-level changes.</p><h3 id="keep-admins-to-a-small-group" tabindex="-1">Keep Admins to a small group <a class="header-anchor" href="#keep-admins-to-a-small-group" aria-label="Permalink to &quot;Keep Admins to a small group&quot;">​</a></h3><p>Admins can change the Organization Description, reassign roles, and archive the organization. Limit Admin access to people who actively manage the workspace — typically the PM lead, product ops, or whoever owns the Lodestone setup.</p><h3 id="always-maintain-a-backup-admin" tabindex="-1">Always maintain a backup Admin <a class="header-anchor" href="#always-maintain-a-backup-admin" aria-label="Permalink to &quot;Always maintain a backup Admin&quot;">​</a></h3><p>Since there must always be at least one Admin, make sure more than one person holds the Admin role. If the sole Admin leaves the company or loses access, you&#39;ll want a backup who can manage the workspace.</p><hr><h2 id="financial-forecast-defaults" tabindex="-1">Financial Forecast Defaults <a class="header-anchor" href="#financial-forecast-defaults" aria-label="Permalink to &quot;Financial Forecast Defaults&quot;">​</a></h2><p>The Financial Forecast module has a set of org-level defaults that apply to all new financial models created in the workspace. These are configured from within the Financial Forecast module (via its Compare view or Settings link), not from the main Settings module.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td>Discount Rate</td><td>12%</td><td>Rate used to calculate NPV in all new models</td></tr><tr><td>Labor Rate</td><td>$15,000/month</td><td>Default cost per engineer for effort-based assumptions</td></tr><tr><td>Fiscal Year Start</td><td>January (month 1)</td><td>Affects how metrics are reported relative to your fiscal year</td></tr><tr><td>Launch Month / Year</td><td>Current year, month 1</td><td>Default launch date used when no per-assumption start month is set</td></tr></tbody></table><p>Changing org-level defaults does not retroactively update existing models — they apply only to new models. Individual models can always override the org defaults at the model level.</p><hr><h2 id="settings-propagation-what-changes-what" tabindex="-1">Settings Propagation: What Changes What <a class="header-anchor" href="#settings-propagation-what-changes-what" aria-label="Permalink to &quot;Settings Propagation: What Changes What&quot;">​</a></h2><p>A quick reference for understanding the ripple effects of Settings changes:</p><table tabindex="0"><thead><tr><th>Setting changed</th><th>Where it affects</th></tr></thead><tbody><tr><td>Organization Description</td><td>All future AI-generated Documents</td></tr><tr><td>Organization Name / Logo</td><td>Workspace display only</td></tr><tr><td>Status Stage renamed</td><td>Feature backlog, all Releases, all Feature views</td></tr><tr><td>Status Stage deleted</td><td>Feature backlog, Releases — affected Features move to default stage</td></tr><tr><td>Evaluation Framework changed</td><td>Feature backlog display, Feature Detail pages</td></tr><tr><td>Strategy Default changed</td><td>Default selection when creating a new Strategy</td></tr><tr><td>Integration connected / disconnected</td><td>Extracts (Fireflies, Gong), Feature sync (JIRA)</td></tr></tbody></table><hr><p><em>Next: Troubleshooting &amp; FAQs — common configuration issues and answers to frequent questions.</em></p>',59)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
